  {m p N : ℕ} {X : Listing G (B.a.S.side m p)} {a : ℝ → Source G (B.a.S.side m p)} {Q : In B.a m p} {l : Set ℝ}
  {H w τ δ b : ℝ → ℝ} {q : ResetPrices} (g : G.Simple) (hm : m < N) (hb : Prices B N m p q l H w δ b)
  (hx : ∀ x ∈ l, Local X (B.a.budget m) (a x) (H x) (w x))
  (he :
    ∀ x ∈ l,
      target Q x =
        earlyValue X (B.kin.path N m) (B.a.params m).clip (B.a.budget m) (a x) (Q x).beta (τ x) (B.kin.alpha N m))
  {x : ℝ} (h : x ∈ l) :
  have A := board B N (ledger B N m p X a);
  have Δ := delta (X.read (a x));
  have v := vac (a x) (τ x);
