  {Q : In B.a m p} {l : Set ℝ} {H w τ δ b : ℝ → ℝ} {q : ResetPrices} (g : G.Simple) (hm : m < N)
  (hb : Prices B N m p q l H w δ b) (hx : ∀ x ∈ l, Local X (B.a.budget m) (a x) (H x) (w x))
  (he :
    ∀ x ∈ l,
      target Q x =
        earlyValue X (B.kin.path N m) (B.a.params m).clip (B.a.budget m) (a x) (Q x).beta (τ x) (B.kin.alpha N m))
  {x : ℝ} (h : x ∈ l) (hp : 0 < target Q x 1) :
  have R := B.kin.path N m;
  have c := (B.a.params m).clip;
  have r := B.a.budget m;
  have d := branch X R c r (a x) (B.kin.alpha N m);
  have _v := scalar (target Q) x;
  ∀ (U : Config G (B.a.S.side m p)),
    (Progress.DirectedRecipe.trunk R c r (shelves X R r) d (predictor B N Q x + delta (X.read (a x))) 0).eval U *
        Real.exp (∑' (i : ℕ), d.logarithm i U) =
      target Q x U / target Q x 1

